24	class MockSessionRepository extends Mock implements SessionRepository {}
25	
26	/// A plain (non-mocktail) fake — the redirect matrix needs [currentStatus]
27	/// read synchronously right after [setStatus], and `statusStream` to
28	/// actually emit so `GoRouterRefreshStream` re-triggers `redirect`; a
29	/// mocktail stub can't do both at once as naturally as this tiny fake.
30	class _FakeSessionRepository implements SessionRepository {
31	  SessionStatus? _status;
32	  final _controller = StreamController<SessionStatus>.broadcast();
33	
34	  @override
35	  SessionStatus? get currentStatus => _status;
36	
37	  @override
38	  Stream<SessionStatus> get statusStream => _controller.stream;
39	
40	  @override
41	  Future<Either<Failure, Unit>> restoreSession() async => right(unit);
42	
43	  @override
44	  void markAuthenticated() => setStatus(SessionStatus.authenticated);
45	
46	  @override
47	  Future<void> dispose() => _controller.close();
48	
49	  void setStatus(SessionStatus status) {
