55	/// A plain (non-mocktail) fake for [VaultRepository], same rationale as
56	/// [_FakeSessionRepository] above — defaults to [VaultStatus.unlocked] so
57	/// every pre-existing (Story 1.6) test case is unaffected by AD-14's new
58	/// gate unless a test explicitly locks it.
59	class _FakeVaultRepository implements VaultRepository {
60	  VaultStatus _status = VaultStatus.unlocked;
61	  final _controller = StreamController<VaultStatus>.broadcast();
62	
63	  /// Controls what [authenticate] resolves to. Defaults to `false` (a
64	  /// quiet failure) so that mounting `VaultLockScreen` in a test — which
65	  /// auto-calls [authenticate] once in `initState` — never silently
66	  /// unlocks the vault on its own; [setStatus] stays the single, explicit
67	  /// way a test flips vault state.
68	  bool authenticateSucceeds = false;
69	
70	  @override
71	  VaultStatus get currentStatus => _status;
72	
73	  @override
74	  Stream<VaultStatus> get statusStream => _controller.stream;
75	
76	  @override
77	  Future<Either<Failure, Unit>> authenticate() async {
78	    if (authenticateSucceeds) {
79	      setStatus(VaultStatus.unlocked);
80	      return right(unit);
81	    }
82	    return left(
83	      const Failure.malformedResponse(message: 'fake: biometrics declined'),
84	    );
85	  }
86	
87	  @override
88	  Future<void> dispose() => _controller.close();
89	
90	  void setStatus(VaultStatus status) {
91	    _status = status;
92	    _controller.add(status);
93	  }
94	}
95	
96	/// Proves the epic's ONE `GoRouter`/`redirect` (Boundaries) resolves the
97	/// I/O & Edge-Case Matrix from spec-1-6/spec-2-1 exactly — composing
98	/// [VaultStatus] first, then [SessionStatus] (AD-14), never a hardcoded
99	/// assumption baked into either matrix.
100	void main() {
101	  late _FakeSessionRepository fakeSessionRepository;
102	  late _FakeVaultRepository fakeVaultRepository;
103	
104	  setUp(() {
105	    fakeSessionRepository = _FakeSessionRepository();
