28	  /// Same rationale as `session_repository_impl_test.dart`'s own
29	  /// `emittedDuring` helper, with one difference: unlike
30	  /// `SessionRepository.statusStream` (nullable, no replay until the first
31	  /// emission), [VaultRepository.statusStream] always synchronously
32	  /// replays the current (never-null) [VaultStatus] to a brand-new
33	  /// listener — so the first element this helper's subscription ever sees
34	  /// is always that initial replay, not an emission caused by [act]. It's
35	  /// drained and discarded here so the returned list reflects only
36	  /// emissions [act] itself caused.
37	  Future<List<VaultStatus>> emittedDuring(
38	    Future<void> Function() act,
39	  ) async {
40	    final emitted = <VaultStatus>[];
41	    final subscription = repository.statusStream.listen(emitted.add);
42	    await Future<void>.delayed(Duration.zero);
43	    emitted.clear();
44	    await act();
45	    await Future<void>.delayed(Duration.zero);
46	    await subscription.cancel();
47	    return emitted;
48	  }
49	
50	  group('VaultStatus.currentStatus — non-nullable, known at construction', () {
51	    test('currentStatus is VaultStatus.locked before any authenticate() '
52	        'call — no async warm-up, unlike SessionStatus (Design Notes)', () {
53	      expect(repository.currentStatus, VaultStatus.locked);
54	    });
55	
56	    test('a listener that subscribes before any authenticate() call still '
57	        'immediately sees VaultStatus.locked, not nothing until the first '
58	        'emission (Stream.multi replay, mirrors SessionRepositoryImpl)', () async {
59	      final status = await repository.statusStream.first;
60	
61	      expect(status, VaultStatus.locked);
62	    });
63	  });
64	
65	  group('cold start, biometrics succeed', () {
66	    test('authenticate() returns true -> statusStream emits unlocked, '
67	        'currentStatus flips to unlocked, Right(unit) returned', () async {
68	      when(
69	        () => mockLocalAuthentication.authenticate(
70	          localizedReason: any(named: 'localizedReason'),
71	          biometricOnly: any(named: 'biometricOnly'),
72	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
73	        ),
74	      ).thenAnswer((_) async => true);
75	
76	      Either<Failure, Unit>? result;
77	      final emitted = await emittedDuring(() async {
78	        result = await repository.authenticate();
79	      });
80	
81	      expect(emitted, [VaultStatus.unlocked]);
82	      expect(repository.currentStatus, VaultStatus.unlocked);
83	      expect(result!.isRight(), isTrue);
84	    });
