87	        '"never set biometricOnly: false" — so the OS\'s own device '
88	        'passcode screen never silently satisfies it', () async {
89	      when(
90	        () => mockLocalAuthentication.authenticate(
91	          localizedReason: any(named: 'localizedReason'),
92	          biometricOnly: any(named: 'biometricOnly'),
93	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
94	        ),
95	      ).thenAnswer((_) async => true);
96	
97	      await repository.authenticate();
98	
99	      verify(
100	        () => mockLocalAuthentication.authenticate(
101	          localizedReason: any(named: 'localizedReason'),
102	          biometricOnly: true,
103	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
104	        ),
105	      ).called(1);
106	    });
107	  });
108	
109	  group('cold start, biometrics fail/cancelled/unavailable', () {
110	    test('authenticate() returns false -> status stays locked, no '
111	        'emission, Left(Failure.malformedResponse), never '
112	        'Failure.authInvalid (Boundaries: reserved for password login)', () async {
113	      when(
114	        () => mockLocalAuthentication.authenticate(
115	          localizedReason: any(named: 'localizedReason'),
116	          biometricOnly: any(named: 'biometricOnly'),
117	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
118	        ),
119	      ).thenAnswer((_) async => false);
120	
121	      Either<Failure, Unit>? result;
122	      final emitted = await emittedDuring(() async {
123	        result = await repository.authenticate();
124	      });
125	
126	      expect(emitted, isEmpty);
127	      expect(repository.currentStatus, VaultStatus.locked);
128	      expect(result!.isLeft(), isTrue);
