135	    test('authenticate() throws LocalAuthException (e.g. user cancelled) '
136	        '-> status stays locked, no emission, Left(Failure.'
137	        'malformedResponse), no crash (RNF09: never let a platform '
138	        'exception escape unmapped)', () async {
139	      when(
140	        () => mockLocalAuthentication.authenticate(
141	          localizedReason: any(named: 'localizedReason'),
142	          biometricOnly: any(named: 'biometricOnly'),
143	          persistAcrossBackgrounding: any(named: 'persistAcrossBackgrounding'),
144	        ),
145	      ).thenThrow(
